def prose(s):
 s=re.sub(r'(?<=[A-Za-z])(?=202[56])',' ',s);s=re.sub(r'(?<=\d)(?=October|December|March|April|January|February|November)',' ',s);s=re.sub(r'Article(?=\d)','Article ',s);s=re.sub(r'(?<=\d)(?=crore|lakh)',' ',s);s=re.sub(r'(?<=[A-Za-z])(?=\d{2}/\d{2})',' ',s);return s
for n in N:
 if n['id'].startswith('E10-'):
  for k in ['title','why','static_link','trap','mains']:n[k]=prose(n[k])
  for k in ['facts','analysis']:n[k]=[prose(x) for x in n[k]]
(R/'data/notes.json').write_text(json.dumps(N,ensure_ascii=False,indent=2)+'\n')
for name in ['data/2026-03-mcqs.json','volumes/March-2026-Mains-Frameworks.md']:
 p=R/name
 if p.suffix=='.json':
  Q=json.loads(p.read_text())
  for q in Q:
   for k in ['question','explanation']:q[k]=prose(q[k])
   q['options']=[prose(x) for x in q['options']]
  p.write_text(json.dumps(Q,ensure_ascii=False,indent=2)+'\n')
 else:p.write_text(prose(p.read_text()))
